style.css:
@-moz-document domain("youtube.com") {
/* Classic light grey background */
  body, html, #background, #page-container, #content {
    background-color: #f1f1f1 !important;
  }

  /* Classic top navigation bar styling */
  #masthead-container, #masthead {
    background-color: #ffffff !important;
    border-bottom: 1px solid #d3d3d3 !important;
  }

  /* Transparent container backgrounds */
  ytd-rich-grid-renderer, ytd-two-column-browse-results-renderer {
    background-color: transparent !important;
  }

  /* Classic squared-off thumbnail corners */
  yt-img-shadow, #thumbnail img {
    border-radius: 2px !important;
  }
}
